// ============================================================================
// CAREER ROLE DEFINITIONS (data only). Add a role = add one line.
//   R(id, name, category, description, coreSkills, optionalSkills, technologies, certifications,
//     relatedRoleIds, exampleProject, searchKeywords, popular?)
// Skill ids come from careerSkills.js; list core skills roughly in learning order.
// The 7 original roles keep their hand-tuned skill graphs (core is "" for them).
// ============================================================================
const ROLE_DEFS = [];
function R(id, name, cat, desc, core, opt, tech, certs, related, project, kw, popular) {
  ROLE_DEFS.push({
    id, name, cat, desc,
    core: core ? core.split(",") : [], opt: opt ? opt.split(",") : [],
    tech: tech ? tech.split(",") : [], certs: certs ? certs.split(";") : [],
    related: related ? related.split(",") : [], project: project || "", kw: kw || "", popular: !!popular,
  });
}

